#include <iostream>
#include <vector>
#include <numeric>
#include <algorithm>

using namespace std;

int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(NULL);

    int n, m;
    if (!(cin >> n >> m)) return 0;

    vector<long long> col_sum(m, 0);

    for (int i = 0; i < n; ++i) {
        for (int j = 0; j < m; ++j) {
            long long val;
            cin >> val;
            col_sum[j] += val;
        }
    }

    long long min_cost = col_sum[0];
    for (int j = 1; j < m; ++j) {
        if (col_sum[j] < min_cost) {
            min_cost = col_sum[j];
        }
    }

    cout << min_cost << "\n";

    return 0;
}
